def word_count(s):
    # Split by whitespace
    tokens = s.split()

    count = 0
    for token in tokens:
        # Remove punctuation from the token
        clean_token = ''.join(c for c in token if c.isalpha())

        # If the token has no letters after removing punctuation, it's not a word
        if len(clean_token) == 0:
            continue

        # Check if it's a single letter - only count if it's a valid single-letter word (a, I)
        if len(clean_token) == 1:
            if clean_token.lower() not in ('a', 'i'):
                continue

        count += 1

    return count

def word_count(s):
    # Split by whitespace
    tokens = s.split()

    count = 0
    for token in tokens:
        # Check if token has at least one letter
        has_letter = False
        for char in token:
            if char.isalpha():
                has_letter = True
                break

        # If token has at least one letter, count it
        if has_letter:
            count += 1

    return count

