def word_count(s):
    # Split by whitespace
    tokens = s.split()

    count = 0
    for token in tokens:
        # Count alphabetic characters in the token
        letter_count = 0
        for char in token:
            if char.isalpha():
                letter_count += 1

        # A token is a word if it has at least 2 letters
        if letter_count >= 2:
            count += 1

    return count

