import re

def slugify(s, mode='basic'):
    """
    Turn a title into a URL slug.

    Args:
        s: The string to slugify
        mode: The mode to use ('basic', 'caps', or 'under')

    Returns:
        The slugified string
    """
    if mode == 'basic':
        # Lowercase all words
        def to_lower(word):
            return word.lower()
    elif mode == 'caps':
        # Capitalize first letter, lowercase rest
        def to_caps(word):
            if not word:
                return ''
            return word[0].upper() + word[1:].lower() if len(word) > 1 else word.upper()
    elif mode == 'under':
        # Keep original case
        def to_under(word):
            return word

    # Split by whitespace to get words
    words = s.split()

    # Process each word
    processed_words = []
    for word in words:
        # Remove punctuation (keep alphanumeric and underscores)
        word = re.sub(r'[^\w]', '', word)
        # Apply the mode
        processed_words.append(to_lower(word))

    # Join with underscores
    result = '_'.join(processed_words)

    return result

